INSERT INTO `child_chunks` VALUES ('3af129a41ca54cf09765dd5ac0c3e02b_0', '3af129a41ca54cf09765dd5ac0c3e02b', '5ecfcafe-d4ad-4c70-910b-c4cb37aabd49', ' asda', '2. 缓存一致性方案: 基于Cache Aside模式解决数据库与缓存的一致性问题。', '3. 高性能缓存策略: 使用Redis对高频访问的信息进行缓存,降低了数据库查询的压力,解决了缓存穿透、雪崩、击穿问题。4. 秒杀资格预检与超卖处理: 使用Redis + Lua脚本实现对用户秒杀资格的预检,同时用乐观锁解决秒杀产生的超卖问题。', 0, 0, 122, 0, 1, NULL, 'student_handbook', 0);
INSERT INTO `child_chunks` VALUES ('3f8694e5b4134ff2a629f6ea3e225763_0', '3f8694e5b4134ff2a629f6ea3e225763', 'fa75dfb1-fffb-43a9-983f-ef5496450d56', '00', '第六章 系统测试', '6.1 测试环境与测试方法6.1.1 测试环境6.1.2 测试方法6.2 功能测试6.2.1 用户管理功能测试6.2.2 文件管理功能测试6.2.3 文件分享功能测试6.3 性能测试6.3.1 响应时间测试6.3.2 并发访问测试6.4 测试结果分析6.5 本章小结', 0, 0, 133, 0, 1, NULL, 'school_overview', 0);
