INSERT INTO `child_chunks` VALUES ('44bfca5b7abc445babdf4638c53d71a9_0', '44bfca5b7abc445babdf4638c53d71a9', '8286128c-ce5f-405b-8a25-cd27561db92a', '集合列表', '03. 推荐遍历方式', '• 索引访问效率高：ArrayList首选普通 for 循环。• 需避免频繁索引查询：LinkedList推荐使用增强 for 循环 / 迭代器。', 0, 0, 73, 0, 1, NULL, 'student_handbook', 0);
INSERT INTO `child_chunks` VALUES ('46fe1ab9ffc445dab3158429caeb5252_0', '46fe1ab9ffc445dab3158429caeb5252', '8286128c-ce5f-405b-8a25-cd27561db92a', '集合列表', '02. Stack：继承自 Vector 的栈', '• 特点：继承 Vector，实现了后进先出 (LIFO)的栈结构。提供 push()、pop()、peek() 方法。• 缺陷：属于 Java 遗留类，设计上存在不完美之处（如继承关系过强）。• 替代：现代开发强烈建议使用Deque 接口(如 LinkedList) 实现栈功能。1.7.2013', 0, 0, 149, 0, 1, NULL, 'student_handbook', 0);
INSERT INTO `child_chunks` VALUES ('46fe1ab9ffc445dab3158429caeb5252_1', '46fe1ab9ffc445dab3158429caeb5252', '8286128c-ce5f-405b-8a25-cd27561db92a', '集合列表', '02. Stack：继承自 Vector 的栈', 'nkedList) 实现栈功能。1.7.2013\n除了ArrayList和LinkedList，Java历史上还有两个重要的List实现：Vector和Stack。Vector是线程安全的ArrayList，但性能较差，现在基本被淘汰。', 0, 125, 243, 0, 1, NULL, 'student_handbook', 0);
INSERT INTO `child_chunks` VALUES ('46fe1ab9ffc445dab3158429caeb5252_2', '46fe1ab9ffc445dab3158429caeb5252', '8286128c-ce5f-405b-8a25-cd27561db92a', '集合列表', '02. Stack：继承自 Vector 的栈', '的ArrayList，但性能较差，现在基本被淘汰。Stack继承自Vector，实现了栈的功能，但同样因为设计问题，现在更推荐用Deque来代替。了解它们主要是为了读懂老代码。‹#›\n实践篇：List的遍历方式\n普通 for 循环\n• 通过索引遍历，适合操作索引场景\n• 强烈推荐用于 ArrayList', 0, 218, 370, 0, 1, NULL, 'student_handbook', 0);
INSERT INTO `child_chunks` VALUES ('46fe1ab9ffc445dab3158429caeb5252_3', '46fe1ab9ffc445dab3158429caeb5252', '8286128c-ce5f-405b-8a25-cd27561db92a', '集合列表', '02. Stack：继承自 Vector 的栈', '作索引场景\n• 强烈推荐用于 ArrayList\n增强 for 循环 (foreach)\n• 语法极其简洁，无需关心索引\n• 适用于 ArrayList 和 LinkedList\n迭代器 (Iterator)\n• 功能最强大，支持遍历中安全删除\n• 适用于 ArrayList 和 LinkedList', 0, 346, 497, 0, 1, NULL, 'student_handbook', 0);
INSERT INTO `child_chunks` VALUES ('46fe1ab9ffc445dab3158429caeb5252_4', '46fe1ab9ffc445dab3158429caeb5252', '8286128c-ce5f-405b-8a25-cd27561db92a', '集合列表', '02. Stack：继承自 Vector 的栈', '于 ArrayList 和 LinkedList\n// 方式1: 普通for循环 (推荐用于ArrayList)\nfor (int i = 0; i < books.size(); i++) { System.out.println(books.get(i)); }\n// 方式2: 增强for循环 (简洁通用)', 0, 473, 629, 0, 1, NULL, 'student_handbook', 0);
INSERT INTO `child_chunks` VALUES ('46fe1ab9ffc445dab3158429caeb5252_5', '46fe1ab9ffc445dab3158429caeb5252', '8286128c-ce5f-405b-8a25-cd27561db92a', '集合列表', '02. Stack：继承自 Vector 的栈', '}\n// 方式2: 增强for循环 (简洁通用)\nfor (String book : books) { System.out.println(book); }\n// 方式3: 迭代器 (支持边遍历边安全删除)\nIterator<String> it = books.iterator(); while(it.', 0, 605, 760, 0, 1, NULL, 'student_handbook', 0);
INSERT INTO `child_chunks` VALUES ('46fe1ab9ffc445dab3158429caeb5252_6', '46fe1ab9ffc445dab3158429caeb5252', '8286128c-ce5f-405b-8a25-cd27561db92a', '集合列表', '02. Stack：继承自 Vector 的栈', 'oks.iterator(); while(it.hasNext()) { it.next(); if(...) it.', 0, 735, 795, 0, 1, NULL, 'student_handbook', 0);
