INSERT INTO `child_chunks` VALUES ('4b7b69c9114f451794961bca12f28a64_0', '4b7b69c9114f451794961bca12f28a64', '9d0255c4-58ee-4753-9a77-433c19c8f1fb', '啊倒萨打算', '### 第 1 章 绪论（优秀论文的\"第一印象\"）', '绪论决定了评审老师对你论文的第一印象，必须体现\"问题意识\"。', 0, 0, 30, 0, 1, NULL, 'announcement', 0);
