INSERT INTO `child_chunks` VALUES ('7d48ea0e08dc49aba012177f4e73d0ed_0', '7d48ea0e08dc49aba012177f4e73d0ed', '9d0255c4-58ee-4753-9a77-433c19c8f1fb', '啊倒萨打算', '## 七、写作流程与时间规划', '建议按以下顺序写作（注意：不是按章节顺序写）：\n```\n第 1 周：第 3 章（需求分析）——对系统最熟悉的部分，先写\n第 2 周：第 4 章（系统设计）——画图 + 写设计说明\n第 3 周：第 5 章（系统实现）——选核心代码 + 截图 + 解释\n第 4 周：第 2 章（技术基础）——用自己的话整理技术原理', 0, 0, 155, 0, 1, NULL, 'announcement', 0);
INSERT INTO `child_chunks` VALUES ('7d48ea0e08dc49aba012177f4e73d0ed_1', '7d48ea0e08dc49aba012177f4e73d0ed', '9d0255c4-58ee-4753-9a77-433c19c8f1fb', '啊倒萨打算', '## 七、写作流程与时间规划', '第 2 章（技术基础）——用自己的话整理技术原理\n第 5 周：第 6 章（测试）——补充测试用例和测试数据\n第 6 周：第 1 章（绪论）——文献综述需要时间\n第 7 周：摘要 + 第 7 章（总结）——最后写摘要\n第 8 周：格式检查 + 查重 + 修改 + 定稿\n```\n---', 0, 131, 272, 0, 1, NULL, 'announcement', 0);
