INSERT INTO `child_chunks` VALUES ('d02e68fa87334ba0aaa043f193ed134b_0', 'd02e68fa87334ba0aaa043f193ed134b', '8286128c-ce5f-405b-8a25-cd27561db92a', '集合列表', '引言', 'contains / clear / subList\n判断包含元素 / 清空列表 / 获取子列表。1.7.2013\n作为一个接口，List定义了一系列操作有序集合的规范。这里列出了最常用的一些方法，比如添加元素的add，获取元素的get，替换元素的set，删除元素的remove等等。理解这些方法是使用List的基础。', 0, 0, 159, 0, 1, NULL, 'student_handbook', 0);
INSERT INTO `child_chunks` VALUES ('d02e68fa87334ba0aaa043f193ed134b_1', 'd02e68fa87334ba0aaa043f193ed134b', '8286128c-ce5f-405b-8a25-cd27561db92a', '集合列表', '引言', 'emove等等。理解这些方法是使用List的基础。右边的图也直观地展示了这些API的用法。接下来我们会通过代码示例来实际感受一下。‹#›\n代码示例：List接口通用API实战\nimportjava.util.ArrayList;importjava.util.List;', 0, 134, 269, 0, 1, NULL, 'student_handbook', 0);
