INSERT INTO `course_selection_schedule` VALUES (2, '2025-2026-2', '第一轮选课（大一大二）', 'SELECTION', '大一,大二', '2026-01-18 08:00:00', '2026-01-20 22:00:00', '第一轮选课', '2026-05-03 12:05:37');
INSERT INTO `course_selection_schedule` VALUES (3, '2025-2026-2', '第二轮补选', 'SELECTION', '全体', '2026-02-25 08:00:00', '2026-02-28 22:00:00', '开学后补选，名额以剩余为准', '2026-05-03 12:05:37');
INSERT INTO `course_selection_schedule` VALUES (4, '2025-2026-2', '退课阶段', 'DROP', '全体', '2026-03-04 08:00:00', '2026-03-07 22:00:00', '可退选已选课程，退课后名额释放', '2026-05-03 12:05:37');
