INSERT INTO `department_contacts` VALUES (2, '计算机学院', 'cs', '李老师', '0571-88002001', 'cs@campus.edu', '信息楼 A201', '周一至周五 9:00-12:00 / 14:30-17:00', '2026-05-03 12:05:37');
INSERT INTO `department_contacts` VALUES (3, '学生处', 'xsc', '张老师', '0571-88003001', 'xsc@campus.edu', '学生活动中心 101', '周一至周五 8:00-17:00', '2026-05-03 12:05:37');
INSERT INTO `department_contacts` VALUES (4, '财务处', 'cwc', '陈老师', '0571-88004001', 'cwc@campus.edu', '行政楼 105', '周一至周五 8:30-11:30 / 13:30-16:30', '2026-05-03 12:05:37');
INSERT INTO `department_contacts` VALUES (5, '图书馆', 'lib', '刘老师', '0571-88005001', 'lib@campus.edu', '图书馆 1F 服务台', '周一至周日 8:00-22:00', '2026-05-03 12:05:37');
INSERT INTO `faq_pairs` VALUES (1, '本学期什么时候选课？', '2025-2026学年第二学期选课时间如下：\n- 大三大四优先：1月15日至17日\n- 大一大二：1月18日至20日\n- 开学补选：2月25日至28日\n- 退课阶段：3月4日至7日\n\n请登录教务系统在规定时间内完成选课。', 'academic', '选课,选课时间,课程', 'HIGH', 1, 142, NULL, '2026-05-03 12:05:37', '2026-05-04 12:07:26');
INSERT INTO `faq_pairs` VALUES (2, '校园卡丢失了怎么办？', '校园卡丢失处理步骤：\n1. 立即登录校园卡网上服务中心挂失，或拨打 0571-88006000\n2. 携带身份证到校园卡服务中心（图书馆1楼）办理补卡\n3. 补卡费工本费20元，2个工作日内可取\n4. 挂失期间不影响门禁正常使用（凭学生证临时通行）', 'campus_service', '校园卡,补卡,挂失', 'HIGH', 1, 87, NULL, '2026-05-03 12:05:37', '2026-05-03 12:05:37');
INSERT INTO `faq_pairs` VALUES (3, 'GPA怎么计算？', '学分绩点（GPA）计算方法：\n\n绩点对应关系：\n- 90-100分：4.0\n- 85-89分：3.7\n- 82-84分：3.3\n- 78-81分：3.0\n- 75-77分：2.7\n- 72-74分：2.3\n- 68-71分：2.0\n- 64-67分：1.5\n- 60-63分：1.0\n- 60分以下：0\n\n平均学分绩点 = Σ(课程学分×绩点) ÷ Σ课程学分', 'academic', 'GPA,绩点,成绩,学分', 'HIGH', 1, 95, NULL, '2026-05-03 12:05:37', '2026-05-03 12:05:37');
INSERT INTO `faq_pairs` VALUES (4, '挂科了怎么办？', '挂科后处理方式：\n①下学期申请重修，重修成绩以实际分计入但标注\"重修\"；\n②学期结束后可参加补考（仅限部分课程）；\n③超过两门必修课不及格需参加学业预警谈话。\n建议尽快联系辅导员了解本院具体规定。教务处：0571-88001001。', 'academic', '挂科,补考,重修,不及格,成绩', 'HIGH', 1, 128, NULL, '2026-05-03 12:05:37', '2026-05-03 12:05:37');
INSERT INTO `faq_pairs` VALUES (5, '如何申请转专业？', '转专业申请流程：\n①每学年第二学期末（5月）开放申请；\n②基本条件：无挂科记录，成绩排名前30%；\n③需通过目标学院专业测试；\n④具体名额和要求参见当年教务处通知。\n申请入口：教务系统→学籍管理→转专业申请。', 'academic', '转专业,申请,绩点,条件', 'HIGH', 1, 73, NULL, '2026-05-03 12:05:37', '2026-05-03 12:05:37');
INSERT INTO `faq_pairs` VALUES (6, '奖学金评定标准是什么？', '国家奖学金：综合测评前0.3%，8000元/人/年；\n国家励志奖学金：前5%且家庭困难，5000元/人/年；\n校一等：前5%，3000元/人/年；\n校二等：前15%，1500元/人/年；\n校三等：前30%，800元/人/年。\n每学年9-10月开始评定，具体通知见校园网。', 'scholarship', '奖学金,评定,综合测评,国家奖学金,励志', 'HIGH', 1, 61, NULL, '2026-05-03 12:05:37', '2026-05-03 12:05:37');
INSERT INTO `faq_pairs` VALUES (7, '毕业论文答辩流程是什么？', '毕业论文答辩流程：\n①3月提交开题报告，导师审核后开始写作；\n②5月初提交初稿，导师修改；\n③5月底完成查重（知网，重复率<15%）；\n④各学院组织答辩（5月下旬至6月初）；\n⑤未通过可申请补答辩（7月）。\n查重入口：教务系统→毕业管理。', 'academic', '毕业论文,答辩,查重,开题,流程', 'HIGH', 1, 55, NULL, '2026-05-03 12:05:37', '2026-05-03 12:05:37');
INSERT INTO `faq_pairs` VALUES (8, '图书馆借书规则是什么？', '本科生可借20册，研究生30册，借期30天，可续借一次（再续30天）。\n逾期费：0.05元/天/册。\n还书：图书馆1楼前台或24小时还书箱（主楼南门旁）。\n电子资源：校园网免费访问CNKI、万方等数据库。', 'library', '图书馆,借书,还书,续借,逾期', 'MEDIUM', 1, 49, NULL, '2026-05-03 12:05:37', '2026-05-03 12:05:37');
INSERT INTO `faq_pairs` VALUES (9, '如何查询期末成绩？', '成绩查询方式：\n①登录教务系统（jwxt.campus.edu）→成绩查询；\n②微信小程序\"校园通\"手机端查询；\n③考试后3-5个工作日出成绩，期末成绩在开学后1-2周内录入。\nGPA计算：Σ(成绩绩点×学分)/总学分，4.0满绩制。', 'academic', '成绩,查询,GPA,绩点,期末', 'MEDIUM', 1, 67, NULL, '2026-05-03 12:05:37', '2026-05-03 12:05:37');
INSERT INTO `faq_pairs` VALUES (10, '宿舍如何报修？', '宿舍报修方式：\n①在线报修（推荐）：校园网→后勤服务→在线报修，1-2工作日上门；\n②电话：后勤保障处 0571-88006001（工作日），宿管室（紧急）；\n③现场：后勤楼102。\n常见小故障可联系楼栋宿管处理。', 'logistics', '宿舍,报修,维修,后勤', 'MEDIUM', 1, 38, NULL, '2026-05-03 12:05:37', '2026-05-03 12:05:37');
INSERT INTO `faq_pairs` VALUES (12, '本学期什么时候选课？（副本）', '2025-2026学年第二学期选课时间如下：\n- 大三大四优先：1月15日至17日\n- 大一大二：1月18日至20日\n- 开学补选：2月25日至28日\n- 退课阶段：3月4日至7日\n\n请登录教务系统在规定时间内完成选课。', 'academic', '选课,选课时间,课程', 'HIGH', 1, 0, NULL, '2026-05-04 12:07:40', '2026-05-04 12:07:40');
INSERT INTO `human_tickets` VALUES (1, 'TK20260301001', 'demo-s001', 1, NULL, '转专业绩点不够如何处理', '学籍管理', 'MEDIUM', 'RESOLVED', '用户询问转专业绩点不满足条件的解决方案。AI已提供相关政策，用户希望了解是否有例外通道。建议：说明特殊申请条件，告知可等待下一年度。', NULL, '2026-05-03 12:05:37', '2026-05-03 12:05:37');
INSERT INTO `human_tickets` VALUES (2, 'TK20260302002', 'demo-s002', 1, 5, '宿舍热水器故障三天无人修理', '设施报修', 'HIGH', 'CLOSED', '用户反映宿舍热水器故障3天，在线报修无响应，情绪较激动。建议立即联系后勤保障处跟进，告知预计修复时间。', NULL, '2026-05-03 12:05:37', '2026-05-04 11:56:00');
INSERT INTO `human_tickets` VALUES (3, 'TK20260303003', 'demo-s003', 1, NULL, '助学金评定结果有异议', '奖助学金', 'MEDIUM', 'RESOLVED', '用户对本学年助学金评定有异议，认为评定不透明。AI已提供申诉流程，建议学生处工作人员介入说明评分细则。', NULL, '2026-05-03 12:05:37', '2026-05-04 11:56:16');
INSERT INTO `human_tickets` VALUES (4, 'TK1777866916900', '5cd75a7cc95d45a7a5e96d99f9662f08', 5, NULL, '申请转人工', '人工服务', 'MEDIUM', 'HANDLING', '用户申请转人工。老师可查看该会话中的学生与 AI 历史记录，并在同一会话回复。', NULL, '2026-05-04 11:55:17', '2026-05-04 13:02:16');
