INSERT INTO `parent_chunks` VALUES ('a9232ef35b7d496aaf84c81e130871fc', '9d0255c4-58ee-4753-9a77-433c19c8f1fb', '啊倒萨打算', '#### 6.3 性能测试（优秀论文的加分利器）', '使用 JMeter 或 Apache Bench 进行压力测试：\n- 测试场景：模拟 100/200/500 并发用户\n- 测试指标：平均响应时间、吞吐量（TPS）、错误率\n- 给出测试结果表格和截图\n- 分析性能瓶颈并提出优化建议', 1, 1, 0, 'announcement', 0, '2026-05-03 23:28:30');
